import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Link } from 'react-router-dom';
import { getAllArtworks, likeArtwork, commentOnArtwork, followArtist } from '../../services/api';
import { setArtworks, setLoading, setError } from '../../store/slices/artworkSlice';
import Navbar from '../../components/Navbar';

const CollectorHome = () => {
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.auth);
  const { artworks } = useSelector((state) => state.artwork);
  const [selectedArtwork, setSelectedArtwork] = useState(null);
  const [comment, setComment] = useState('');
  const [followedArtists, setFollowedArtists] = useState(new Set());
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchArtworks = async () => {
      dispatch(setLoading(true));
      try {
        const data = await getAllArtworks();
        dispatch(setArtworks(data));
      } catch (error) {
        dispatch(setError(error.message));
      } finally {
        setIsLoading(false);
      }
    };

    fetchArtworks();
  }, [dispatch]);

  const handleLike = async (artworkId) => {
    try {
      await likeArtwork(artworkId);
      dispatch(setArtworks(artworks.map(artwork => 
        artwork.id === artworkId 
          ? { ...artwork, likes: artwork.likes + 1, isLiked: true }
          : artwork
      )));
    } catch (error) {
      console.error('Error liking artwork:', error);
    }
  };

  const handleComment = async (artworkId) => {
    if (!comment.trim()) return;

    try {
      await commentOnArtwork(artworkId, comment);
      dispatch(setArtworks(artworks.map(artwork => 
        artwork.id === artworkId 
          ? { 
              ...artwork, 
              comments: [...artwork.comments, { 
                id: Date.now(), 
                text: comment, 
                user: user.name,
                date: new Date().toISOString()
              }]
            }
          : artwork
      )));
      setComment('');
    } catch (error) {
      console.error('Error commenting on artwork:', error);
    }
  };

  const handleFollowArtist = async (artistId) => {
    try {
      await followArtist(artistId);
      setFollowedArtists(prev => new Set([...prev, artistId]));
    } catch (error) {
      console.error('Error following artist:', error);
    }
  };

  const handleOrder = (artwork) => {
    // Implement order functionality
    console.log('Ordering artwork:', artwork);
  };

  if (!user) {
    return null;
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-cream flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-coral"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-cream">
      <Navbar userType="collector" />

      {/* Hero Section */}
      <div className="relative bg-brown text-white">
        <div className="absolute inset-0 bg-black/50"></div>
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
          <div className="text-center">
            <h1 className="text-4xl md:text-6xl font-bold mb-6">Discover Unique Artworks</h1>
            <p className="text-xl md:text-2xl mb-8 max-w-3xl mx-auto">
              Explore our curated collection of exceptional artworks from talented artists around the world.
            </p>
            <Link
              to="/collector/gallery"
              className="bg-coral text-white px-8 py-3 rounded-lg text-lg font-semibold hover:bg-salmon transition-colors"
            >
              Browse Gallery
            </Link>
          </div>
        </div>
      </div>

      {/* Featured Categories */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <h2 className="text-3xl font-bold text-brown mb-8 text-center">Featured Categories</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {['Paintings', 'Sculptures', 'Photography', 'Digital Art'].map((category) => (
            <div
              key={category}
              className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow"
            >
              <div className="aspect-w-1 aspect-h-1">
                <img
                  src={`https://source.unsplash.com/random/400x400?${category.toLowerCase()}`}
                  alt={category}
                  className="w-full h-full object-cover"
                />
              </div>
              <div className="p-4">
                <h3 className="text-lg font-semibold text-brown">{category}</h3>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Featured Artworks */}
      <div className="bg-white py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h2 className="text-3xl font-bold text-brown mb-8 text-center">Featured Artworks</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {artworks.slice(0, 3).map((artwork) => (
              <div key={artwork.id} className="bg-white rounded-lg shadow-md overflow-hidden">
                <img
                  src={artwork.imageUrl}
                  alt={artwork.title}
                  className="w-full h-64 object-cover cursor-pointer"
                  onClick={() => setSelectedArtwork(artwork)}
                />
                <div className="p-6">
                  <h3 className="text-xl font-semibold text-brown mb-2">{artwork.title}</h3>
                  <p className="text-brown/70 mb-4">by {artwork.artistName}</p>
                  <div className="flex justify-between items-center mb-4">
                    <button
                      onClick={() => handleLike(artwork.id)}
                      className={`flex items-center space-x-2 ${
                        artwork.isLiked ? 'text-coral' : 'text-brown/50'
                      } hover:text-coral`}
                    >
                      <span>❤</span>
                      <span>{artwork.likes} Likes</span>
                    </button>
                    <span className="text-brown/50">{artwork.comments.length} Comments</span>
                  </div>
                  <button
                    onClick={() => handleOrder(artwork)}
                    className="w-full bg-coral text-white py-2 rounded-lg hover:bg-salmon transition-colors"
                  >
                    Order Now
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* All Artworks */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <h2 className="text-3xl font-bold text-brown mb-8 text-center">All Artworks</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {artworks.map((artwork) => (
            <div key={artwork.id} className="bg-white rounded-lg shadow-md overflow-hidden">
              <img
                src={artwork.imageUrl}
                alt={artwork.title}
                className="w-full h-48 object-cover cursor-pointer"
                onClick={() => setSelectedArtwork(artwork)}
              />
              <div className="p-4">
                <h3 className="font-semibold text-brown">{artwork.title}</h3>
                <div className="flex justify-between items-center mt-2">
                  <p className="text-sm text-brown/70">{artwork.artistName}</p>
                  <button
                    onClick={() => handleFollowArtist(artwork.artistId)}
                    className={`text-sm ${followedArtists.has(artwork.artistId) ? 'text-coral' : 'text-brown/50'} hover:text-coral`}
                  >
                    {followedArtists.has(artwork.artistId) ? 'Following' : 'Follow'}
                  </button>
                </div>
                <div className="flex justify-between items-center mt-2">
                  <span className="text-coral font-semibold">${artwork.price}</span>
                  <div className="flex items-center space-x-2">
                    <button
                      onClick={() => handleLike(artwork.id)}
                      className={`text-sm ${artwork.isLiked ? 'text-coral' : 'text-brown/50'} hover:text-coral`}
                    >
                      {artwork.likes} Likes
                    </button>
                    <span className="text-sm text-brown/50">{artwork.comments.length} Comments</span>
                  </div>
                </div>
                <button
                  onClick={() => handleOrder(artwork)}
                  className="mt-4 w-full bg-coral text-white py-2 rounded-lg hover:bg-salmon transition-colors"
                >
                  Order Now
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Artwork Details Modal */}
      {selectedArtwork && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h2 className="text-2xl font-bold text-brown">{selectedArtwork.title}</h2>
                  <p className="text-brown/70">by {selectedArtwork.artistName}</p>
                </div>
                <button
                  onClick={() => setSelectedArtwork(null)}
                  className="text-brown/50 hover:text-brown"
                >
                  ✕
                </button>
              </div>

              <img
                src={selectedArtwork.imageUrl}
                alt={selectedArtwork.title}
                className="w-full h-96 object-contain mb-4"
              />

              <p className="text-brown mb-4">{selectedArtwork.description}</p>

              <div className="space-y-4">
                <div className="flex items-center space-x-4">
                  <button
                    onClick={() => handleLike(selectedArtwork.id)}
                    className={`flex items-center space-x-2 ${
                      selectedArtwork.isLiked ? 'text-coral' : 'text-brown/50'
                    } hover:text-coral`}
                  >
                    <span>❤</span>
                    <span>{selectedArtwork.likes} Likes</span>
                  </button>
                  <button
                    onClick={() => handleFollowArtist(selectedArtwork.artistId)}
                    className={`text-coral hover:text-salmon ${
                      followedArtists.has(selectedArtwork.artistId) ? 'font-semibold' : ''
                    }`}
                  >
                    {followedArtists.has(selectedArtwork.artistId) ? 'Following Artist' : 'Follow Artist'}
                  </button>
                  <Link
                    to={`/artist/${selectedArtwork.artistId}`}
                    className="text-coral hover:text-salmon"
                  >
                    Contact Artist
                  </Link>
                </div>

                <div className="border-t border-brown/20 pt-4">
                  <h3 className="font-semibold text-brown mb-2">Comments</h3>
                  <div className="space-y-4">
                    {selectedArtwork.comments.map((comment) => (
                      <div key={comment.id} className="bg-brown/5 p-3 rounded-lg">
                        <div className="flex justify-between items-start">
                          <span className="font-semibold text-brown">{comment.user}</span>
                          <span className="text-sm text-brown/50">
                            {new Date(comment.date).toLocaleDateString()}
                          </span>
                        </div>
                        <p className="text-brown/80 mt-1">{comment.text}</p>
                      </div>
                    ))}
                  </div>

                  <div className="mt-4">
                    <textarea
                      value={comment}
                      onChange={(e) => setComment(e.target.value)}
                      placeholder="Add a comment..."
                      className="w-full p-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
                      rows="2"
                    />
                    <button
                      onClick={() => handleComment(selectedArtwork.id)}
                      className="mt-2 px-4 py-2 bg-coral text-white rounded-lg hover:bg-salmon transition-colors"
                    >
                      Post Comment
                    </button>
                  </div>
                </div>

                <button
                  onClick={() => handleOrder(selectedArtwork)}
                  className="w-full mt-4 bg-coral text-white py-3 rounded-lg hover:bg-salmon transition-colors"
                >
                  Order Now
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CollectorHome;
